// Pseudocode for routing decision
function route(request, tenancy, pools, metrics) {
  const budget = tenancy.latencyBudget;
  const eta = estimateETA(request, pools, metrics);
  const chosen = (eta <= budget) ? selectPool(pools, tenancy) : escalateFallback(tenancy);
  return chosen;
}
```

